<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/admin-ui.php';require_once __DIR__.'/blog-lib.php';$u=require_admin();$db=blog_db();$id=(int)($_GET['id']??0);$err='';$p=['title'=>'','slug'=>'','category_id'=>'','excerpt'=>'','content'=>'','featured_image'=>'','featured_image_alt'=>'','status'=>'draft','published_at'=>'','meta_title'=>'','meta_description'=>'','focus_keyword'=>'','secondary_keywords'=>'','canonical_url'=>'','robots'=>'index,follow','og_title'=>'','og_description'=>'','og_image'=>'','schema_json'=>''];if($id){$q=$db->prepare('SELECT * FROM posts WHERE id=?');$q->execute([$id]);$stored=$q->fetch();if(!$stored){http_response_code(404);exit('Post not found.');}$p=array_merge($p,array_map(static fn($value)=>$value??'', $stored));if(!post_owner($u,$p)){http_response_code(403);exit('Not permitted.');}}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$oldSlug=(string)($p['slug']??'');$p=array_merge($p,['title'=>clean_text($_POST['title']??'',255),'slug'=>admin_slug($_POST['slug']?:$_POST['title']??''),'category_id'=>(int)($_POST['category_id']??0),'excerpt'=>clean_text($_POST['excerpt']??'',1000),'content'=>clean_text($_POST['content']??'',50000),'featured_image_alt'=>clean_text($_POST['featured_image_alt']??'',255),'status'=>valid_post_status($_POST['status']??'draft'),'meta_title'=>clean_text($_POST['meta_title']??'',255),'meta_description'=>clean_text($_POST['meta_description']??'',320),'focus_keyword'=>clean_text($_POST['focus_keyword']??'',160),'secondary_keywords'=>clean_text($_POST['secondary_keywords']??'',500),'canonical_url'=>trim($_POST['canonical_url']??''),'robots'=>in_array($_POST['robots']??'', ['index,follow','noindex,follow','index,nofollow','noindex,nofollow'],true)?$_POST['robots']:'index,follow','og_title'=>clean_text($_POST['og_title']??'',255),'og_description'=>clean_text($_POST['og_description']??'',320),'og_image'=>trim($_POST['og_image']??''),'schema_json'=>trim($_POST['schema_json']??'')]);try{$image=safe_image_upload('featured_image');if($image)$p['featured_image']=$image;if(!$p['title']||!$p['content'])throw new RuntimeException('Title and content are required.');if($p['canonical_url']&&!filter_var($p['canonical_url'],FILTER_VALIDATE_URL))throw new RuntimeException('Canonical URL is invalid.');if($p['schema_json']&&json_decode($p['schema_json'])===null)throw new RuntimeException('Schema JSON is invalid.');$q=$db->prepare('SELECT id FROM posts WHERE slug=? AND id!=?');$q->execute([$p['slug'],$id]);if($q->fetch())throw new RuntimeException('That slug is already in use.');if(!post_publishable($u)&&$p['status']==='published')$p['status']='draft';$fields=['title','slug','category_id','excerpt','content','featured_image','featured_image_alt','meta_title','meta_description','focus_keyword','secondary_keywords','canonical_url','robots','og_title','og_description','og_image','schema_json','status'];$vals=array_map(fn($f)=>$p[$f]?:null,$fields);if($id){$sets=implode(',',array_map(fn($f)=>$f.'=?',$fields));$db->prepare("UPDATE posts SET $sets,updated_at=CURRENT_TIMESTAMP,published_at=CASE WHEN ?='published' AND published_at IS NULL THEN CURRENT_TIMESTAMP ELSE published_at END WHERE id=?")->execute([...$vals,$p['status'],$id]);if($oldSlug!==''&&$oldSlug!==$p['slug']){try{$redirect=$db->prepare('SELECT id FROM redirects WHERE from_path=?');$redirect->execute(['blog/'.$oldSlug.'/']);if(!$redirect->fetch()){$redirect=$db->prepare('INSERT INTO redirects(from_path,to_path) VALUES(?,?)');$redirect->execute(['blog/'.$oldSlug.'/','/blog/'.$p['slug'].'/']);}}catch(Throwable $ignored){}}audit($db,$u,$p['status']==='published'?'publish':'update','post',$id);}else{$db->prepare('INSERT INTO posts('.implode(',',$fields).',author_id,published_at) VALUES('.rtrim(str_repeat('?,',count($fields)+2),',').')')->execute([...$vals,$u['id'],$p['status']==='published'?date('Y-m-d H:i:s'):null]);$id=(int)$db->lastInsertId();audit($db,$u,$p['status']==='published'?'publish':'create','post',$id);}header('Location: /admin/post-edit.php?id='.$id.'&saved=1');exit;}catch(Throwable$e){$err=$e->getMessage();}}
$cats=$db->query('SELECT id,name FROM categories WHERE status="active" ORDER BY name')->fetchAll();admin_layout_start($id?'Edit post':'New post','posts',$u);?><div class="bar"><h1><?=$id?'Edit post':'New post'?></h1><a class="btn alt" href="/admin/posts.php">Back to posts</a></div><?php if($err):?><p class="notice" style="background:#fff0f0;color:#8b1e1e"><?=htmlspecialchars($err)?></p><?php endif?><form method="post" enctype="multipart/form-data" class="grid"><section class="card"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Title</label><input name="title" required value="<?=htmlspecialchars($p['title'])?>"><label>Slug</label><input name="slug" value="<?=htmlspecialchars($p['slug'])?>"><label>Category</label><select name="category_id"><option value="">None</option><?php foreach($cats as$c):?><option value="<?=$c['id']?>" <?=$p['category_id']==$c['id']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach?></select><label>Excerpt</label><textarea name="excerpt"><?=htmlspecialchars($p['excerpt'])?></textarea><label>Content</label><textarea name="content" required><?=htmlspecialchars($p['content'])?></textarea><label>Featured image (JPG, PNG, WEBP; max 5 MB)</label><input name="featured_image" type="file" accept="image/jpeg,image/png,image/webp"><label>Image alt text</label><input name="featured_image_alt" value="<?=htmlspecialchars($p['featured_image_alt'])?>"></section><aside class="card"><label>Status</label><select name="status"><option value="draft">Draft</option><?php if(post_publishable($u)):?><option value="published" <?=$p['status']==='published'?'selected':''?>>Published</option><?php endif?></select><h2>SEO</h2><?php foreach(['meta_title'=>'Meta title','focus_keyword'=>'Focus keyword','secondary_keywords'=>'Secondary keywords','canonical_url'=>'Canonical URL','og_title'=>'OG title','og_image'=>'OG image URL']as$f=>$l):?><label><?=$l?></label><input name="<?=$f?>" value="<?=htmlspecialchars($p[$f])?>"><?php endforea